CREATE TABLE socios (id INTEGER PRIMARY KEY, nombre TEXT NOT NULL UNIQUE, telefono TEXT);
CREATE TABLE instructores (id INTEGER PRIMARY KEY, nombre TEXT NOT NULL UNIQUE, telefono TEXT);
CREATE TABLE clases (id INTEGER PRIMARY KEY, nombre TEXT NOT NULL UNIQUE, horario TEXT NOT NULL,
                     instructor_id INTEGER NOT NULL REFERENCES instructores(id));
CREATE TABLE inscripciones (
  socio_id  INTEGER NOT NULL REFERENCES socios(id),
  clase_id  INTEGER NOT NULL REFERENCES clases(id),
  fecha     TEXT NOT NULL,
  PRIMARY KEY (socio_id, clase_id)
);
INSERT INTO socios (nombre, telefono) SELECT DISTINCT socio, telefono_socio FROM hoja;
INSERT INTO instructores (nombre, telefono) SELECT DISTINCT instructor, telefono_instructor FROM hoja;
INSERT INTO clases (nombre, horario, instructor_id)
SELECT DISTINCT h.clase, h.horario, i.id FROM hoja AS h JOIN instructores AS i ON i.nombre = h.instructor;
INSERT INTO inscripciones (socio_id, clase_id, fecha)
SELECT s.id, c.id, h.fecha_inscripcion
FROM hoja AS h
JOIN socios AS s ON s.nombre = h.socio
JOIN clases AS c ON c.nombre = h.clase;
SELECT s.nombre AS socio, s.telefono, c.nombre AS clase, i.nombre AS instructor, i.telefono, c.horario, ins.fecha
FROM inscripciones AS ins
JOIN socios AS s ON s.id = ins.socio_id
JOIN clases AS c ON c.id = ins.clase_id
JOIN instructores AS i ON i.id = c.instructor_id
ORDER BY socio, clase;

