CREATE TABLE clientes_feria (
  id              INTEGER PRIMARY KEY,
  nombre          TEXT NOT NULL,
  email           TEXT UNIQUE CHECK (email LIKE '%_@_%._%'),
  telefono        TEXT CHECK (telefono GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9]'),
  provincia_id    INTEGER NOT NULL REFERENCES provincias(id),
  fecha_registro  TEXT NOT NULL CHECK (fecha_registro GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  edad            INTEGER CHECK (edad BETWEEN 0 AND 120)
);
UPDATE clientes_import SET email = NULL WHERE email NOT LIKE '%_@_%._%';
INSERT INTO clientes_feria (id, nombre, email, telefono, provincia_id, fecha_registro, edad)
SELECT ci.id, ci.nombre, ci.email, ci.telefono, p.id, ci.fecha_registro, ci.edad
FROM clientes_import AS ci
JOIN provincias AS p ON p.nombre = ci.provincia;
COMMIT;
SELECT (SELECT COUNT(*) FROM clientes_import) AS limpias,
       (SELECT COUNT(*) FROM clientes_feria) AS cargadas;

